    const decoded = Buffer.from(parts[0], 'base64url');
    if (decoded.toString('base64url') !== parts[0]) return null;
    const payload = JSON.parse(decoded.toString('utf8'));
    if (!payload || typeof payload.subject !== 'string' || payload.subject.length === 0 ||
        typeof payload.role !== 'string' || payload.role.length === 0 ||
        !Number.isInteger(payload.expires)) return null;
