'use strict';

const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['authorizePass']);
assert.equal(typeof api.authorizePass, 'function');
const { authorizePass } = api;

function pass(payload, key) {
  const encoded = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
  const signature = crypto.createHmac('sha256', key).update(encoded).digest('hex');
  return `${encoded}.${signature}`;
}

const keys = { entryKey: 'entry-secret', renewalKey: 'renewal-secret' };
const now = 1700000000;
const validEntry = pass({ subject: 'user-1', role: 'admin', expires: now + 1 }, keys.entryKey);

assert.deepEqual(
  authorizePass({ headers: { 'X-Entry-Pass': validEntry }, now }, keys),
  { ok: true, status: 200, role: 'admin' }
);
assert.deepEqual(
  authorizePass({ headers: {}, now }, keys),
  { ok: false, status: 401, message: 'Entry pass required' }
);

for (const bad of [
  'not-a-pass',
  'e30.' + '0'.repeat(64),
  pass({ subject: '', role: 'admin', expires: now + 10 }, keys.entryKey),
  pass({ subject: 'u', role: 'admin', expires: 1.5 }, keys.entryKey),
  pass({ subject: 'u', role: 'admin', expires: now + 10 }, 'wrong-key')
]) {
  assert.deepEqual(
    authorizePass({ headers: { 'x-entry-pass': bad }, now }, keys),
    { ok: false, status: 401, message: 'Invalid entry pass' }
  );
}

const renewal = pass({ subject: 'renewed-user', role: 'editor', expires: now + 50 }, keys.renewalKey);
const expectedRenewed = pass({ subject: 'renewed-user', role: 'editor', expires: now + 300 }, keys.entryKey);
assert.deepEqual(
  authorizePass({ headers: { 'x-renewal-pass': renewal }, now }, keys),
  { ok: true, status: 200, role: 'editor', renewedPass: expectedRenewed }
);

const expiredEntry = pass({ subject: 'old-user', role: 'viewer', expires: now }, keys.entryKey);
assert.deepEqual(
  authorizePass({ headers: { 'X-Entry-Pass': expiredEntry, 'X-Renewal-Pass': renewal }, now }, keys),
  { ok: true, status: 200, role: 'editor', renewedPass: expectedRenewed }
);
assert.deepEqual(
  authorizePass({ headers: { 'x-entry-pass': expiredEntry }, now }, keys),
  { ok: false, status: 401, message: 'Renewal rejected' }
);
assert.deepEqual(
  authorizePass({ headers: { 'x-entry-pass': expiredEntry, 'x-renewal-pass': pass({ subject: 'u', role: 'r', expires: now }, keys.renewalKey) }, now }, keys),
  { ok: false, status: 401, message: 'Renewal rejected' }
);

// A present, invalid entry pass takes precedence over a renewal pass.
assert.deepEqual(
  authorizePass({ headers: { 'x-entry-pass': 'bad', 'x-renewal-pass': renewal }, now }, keys),
  { ok: false, status: 401, message: 'Invalid entry pass' }
);

for (const args of [
  [null, keys],
  [{ headers: {}, now: 1.5 }, keys],
  [{ headers: [], now }, keys],
  [{ headers: {}, now }, { entryKey: '', renewalKey: 'x' }],
  [{ headers: {}, now }, { entryKey: 'x', renewalKey: '' }]
]) {
  assert.deepEqual(authorizePass(...args), { ok: false, status: 401, message: 'Invalid entry pass' });
}

const request = { headers: { 'x-entry-pass': validEntry }, now };
const requestSnapshot = JSON.stringify(request);
const keysSnapshot = JSON.stringify(keys);
authorizePass(request, keys);
assert.equal(JSON.stringify(request), requestSnapshot);
assert.equal(JSON.stringify(keys), keysSnapshot);

